public class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failedSaves = new Map<Id, String>();

        // Guard against null or empty input so we do not build a SOQL IN clause with null values.
        if (contactIds == null || contactIds.isEmpty()) {
            return failedSaves;
        }

        List<Id> validIds = new List<Id>();
        for (Id id : contactIds) {
            if (String.isNotBlank(id)) {
                validIds.add(id);
            }
        }

        if (validIds.isEmpty()) {
            return failedSaves;
        }

        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :validIds
            WITH SECURITY ENFORCED
        ];

        List<Contact> contactsToSave = new List<Contact>();

        for (Contact contact : contacts) {
            if (String.isNotBlank(contact.Phone)) {
                contact.Phone = removeNonPhoneCharacters(contact.Phone);
                contactsToSave.add(contact);
            }
        }

        // Avoid DML when there is nothing to save.
        if (!contactsToSave.isEmpty()) {
            List<Database.SaveResult> saveResults = Database.update(contactsToSave, false);

            for (Database.SaveResult saveResult : saveResults) {
                if (!saveResult.isSuccess()) {
                    List<Database.Error> errors = saveResult.getErrors();
                    String firstError = (errors != null && !errors.isEmpty())
                        ? errors.get(0).getMessage()
                        : 'Unknown DML error';

                    failedSaves.put(saveResult.getId(), firstError);
                }
            }
        }

        return failedSaves;
    }

    private static String removeNonPhoneCharacters(String phone) {
        if (String.isBlank(phone)) {
            return null;
        }

        // Keeps only digits and plus signs, per the requested transformation.
        return phone.replaceAll('[^0-9+]', '');
    }
}
