/**
 * Returns opportunity Amount totals for the four open pipeline stages for a date range.
 *
 * In a production codebase I would usually prefer one GROUP BY SOQL so the number of
 * queries does not grow with the number of stages and the stage list can be data-driven.
 * The requirement here is a fixed set of four stages, so one simple SUM query per stage
 * is acceptable and easier to read.
 */
public with sharing class PipelineSummary {
    private static final List<String> OPEN_STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();

        for (String stage : OPEN_STAGES) {
            totals.put(stage, 0);
        }

        if (fromDate == null || toDate == null) {
            return totals;
        }

        for (String stage : OPEN_STAGES) {
            String soql =
                'SELECT SUM(Amount) stageTotal ' +
                'FROM Opportunity ' +
                'WHERE StageName = :stage ' +
                'AND CloseDate >= :fromDate ' +
                'AND CloseDate <= :toDate';

            AggregateResult row = [soql];
            Decimal stageTotal = (Decimal) row.get('stageTotal');

            if (stageTotal == null) {
                stageTotal = 0;
            }

            totals.put(stage, stageTotal);
        }

        return totals;
    }
}
