public class StaleOpportunityCloser {
    /**
     * Closes open opportunities whose close date is before the supplied cutoff date.
     *
     * Uses a SOQL for-loop so Salesforce returns chunks of up to 200 records at a time,
     * avoiding holding the full result set in memory. This is appropriate for the stated
     * few-thousand nightly volume. If the volume could grow much larger, I would move
     * this to Batch Apex to stay within transaction governor limits and get better
     * resume/reporting behavior.
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            return 0;
        }

        Integer closedCount = 0;

        for (List<Opportunity> chunk : [
                SELECT Id
                FROM Opportunity
                WHERE IsClosed = false
                AND CloseDate < :cutoff
        ]) {
            for (Opportunity opportunity : chunk) {
                opportunity.StageName = 'Closed Lost';
            }

            update chunk;
            closedCount += chunk.size();
        }

        return closedCount;
    }
}
