public class AccountRatingService with sharing {
    private static final Currency HOT_AMOUNT_THRESHOLD = 100000;
    private static final Integer QUERY_BATCH_SIZE = 500;

    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        for (List<Id> chunk : chunkIds(accountIds, QUERY_BATCH_SIZE)) {
            recalculateChunk(new Set<Id>(chunk));
        }
    }

    private static void recalculateChunk(Set<Id> accountIds) {
        AggregateResult[] hotResults = [
            SELECT AccountId
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            AND Amount != null
            AND Amount >= :HOT_AMOUNT_THRESHOLD
            GROUP BY AccountId
        ];

        Set<Id> hotAccounts = new Set<Id>();
        for (AggregateResult result : hotResults) {
            hotAccounts.add((Id)result.get('AccountId'));
        }

        AggregateResult[] openResults = [
            SELECT AccountId
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ];

        Set<Id> openAccounts = new Set<Id>();
        for (AggregateResult result : openResults) {
            openAccounts.add((Id)result.get('AccountId'));
        }

        List<Account> accounts = [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ];

        List<Account> updates = new List<Account>();

        for (Account acc : accounts) {
            String expectedRating;

            if (hotAccounts.contains(acc.Id)) {
                expectedRating = 'Hot';
            } else if (openAccounts.contains(acc.Id)) {
                expectedRating = 'Warm';
            } else {
                expectedRating = 'Cold';
            }

            if (acc.Rating != expectedRating) {
                acc.Rating = expectedRating;
                updates.add(acc);
            }
        }

        if (!updates.isEmpty()) {
            update updates;
        }
    }

    private static List<List<Id>> chunkIds(Set<Id> ids, Integer batchSize) {
        List<List<Id>> chunks = new List<List<Id>>();

        if (ids == null || ids.isEmpty() || batchSize == null || batchSize <= 0) {
            return chunks;
        }

        List<Id> idList = new List<Id>(ids);

        for (Integer i = 0; i < idList.size(); i += batchSize) {
            List<Id> chunk = new List<Id>();
            Integer end = i + batchSize;

            if (end > idList.size()) {
                end = idList.size();
            }

            for (Integer j = i; j < end; j++) {
                chunk.add(idList[j]);
            }

            chunks.add(chunk);
        }

        return chunks;
    }
}
