public with sharing class LeadContactMatcher {
    /*
     * I would use a map instead of a nested loop. The data size is small enough that
     * a nested loop would likely work, but a map avoids up to 9,000,000 comparisons
     * for 3,000 leads and 3,000 contacts inside the import transaction while still
     * preserving first-contact-wins behavior. It performs no SOQL or DML.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> result = new List<Id>();
        if (leads == null) {
            return result;
        }

        Map<String, Id> contactByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact contact : contacts) {
                if (contact == null) {
                    continue;
                }

                String normalizedEmail = normalizeEmail(contact.Email);
                if (normalizedEmail == null) {
                    continue;
                }

                // First contact in the provided list wins.
                if (!contactByEmail.containsKey(normalizedEmail)) {
                    contactByEmail.put(normalizedEmail, contact.Id);
                }
            }
        }

        for (Lead lead : leads) {
            if (lead == null) {
                result.add(null);
                continue;
            }

            String normalizedEmail = normalizeEmail(lead.Email);
            result.add(normalizedEmail == null ? null : contactByEmail.get(normalizedEmail));
        }

        return result;
    }

    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }

        String trimmed = email.trim();
        if (trimmed.length() == 0) {
            return null;
        }

        return trimmed.toLowerCase();
    }
}
