// After-update trigger for Case.
// Enqueues a separate CaseSurveyJob for every case that transitions from not closed to closed.
// One job per case keeps bulk close operations isolated: a failure on one case does not
// prevent the other cases from being processed.
trigger CaseTrigger on Case after update {
    // Collect the case IDs that actually changed from not closed to closed.
    Set<Id> newlyClosedCaseIds = new Set<Id>();

    for (Case c : Trigger.New) {
        Case oldCase = Trigger.OldMap.get(c.Id);
        if (oldCase != null && !oldCase.IsClosed && c.IsClosed) {
            newlyClosedCaseIds.add(c.Id);
        }
    }

    // Enqueue one queueable job per newly closed case.
    // The job will no-op if the case has no Contact, so no Task is created for cases without a contact.
    for (Id caseId : newlyClosedCaseIds) {
        System.enqueueJob(new CaseSurveyJob(caseId));
    }
}
