// Queueable job that creates a CSAT survey Task for a single Case.
// It is intentionally designed to process exactly one Case so that bulk close operations
// remain isolated and one failure cannot affect the others.
public with sharing class CaseSurveyJob implements Queueable {
    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        // Re-query the case in the async context. This avoids relying on trigger state that
        // may have changed before the job runs and ensures we only create a survey for a
        // closed case that has a Contact.
        List<Case> caseList = [SELECT Id, CaseNumber, ContactId, IsClosed
                               FROM Case
                               WHERE Id = :caseId
                               LIMIT 1];

        if (caseList.isEmpty()) {
            return;
        }

        Case cs = caseList[0];

        // Cases without a contact get no task.
        // If the case was reopened before this job ran, do not create a survey task.
        if (!cs.IsClosed || cs.ContactId == null) {
            return;
        }

        Task surveyTask = new Task(
            WhatId = cs.Id,
            WhoId = cs.ContactId,
            Subject = 'CSAT survey: ' + cs.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );

        insert surveyTask;
    }
}
