/**
 * Sends one renewal reminder email to each opportunity owner.
 *
 * Production caveat: the requested pattern of calling Messaging.sendEmail once
 * per opportunity for up to 200 opportunities in a single transaction is not
 * safe. Apex enforces a per-transaction email limit for Messaging.sendEmail
 * (currently 10). Emails to internal users by user ID do not consume the
 * daily external email allocation, but they still require a safe transaction
 * design for large volumes. For production, chunk this work into separate
 * transactions, such as batch Apex or a queueable chain, or limit this method
 * to a small number of records.
 */
public class RenewalReminderService {
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }

        if (uniqueOpportunityIds.isEmpty()) {
            return 0;
        }

        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>(
            [SELECT Id, Name, OwnerId, CloseDate FROM Opportunity WHERE Id IN :uniqueOpportunityIds]
        );

        Integer sentCount = 0;

        for (Id opportunityId : uniqueOpportunityIds) {
            Opportunity opportunity = opportunitiesById.get(opportunityId);

            if (opportunity == null
                || String.isBlank(opportunity.Name)
                || opportunity.OwnerId == null) {
                continue;
            }

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opportunity.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opportunity.Name);

            String closeDateText = opportunity.CloseDate == null
                ? 'not set'
                : opportunity.CloseDate.format();

            email.setPlainTextBody(
                'Hello,\n\n' +
                'The opportunity ' + opportunity.Name + ' is due for renewal.\n' +
                'Close date: ' + closeDateText + '\n\n' +
                'Please follow up before the close date.\n'
            );

            try {
                Messaging.EmailSendStatus[] statuses =
                    Messaging.sendEmail(new List<Messaging.SingleEmailMessage> { email });

                if (statuses != null && !statuses.isEmpty() && statuses[0].isSuccess()) {
                    sentCount++;
                }
            } catch (LimitExceededException lex) {
                System.debug(
                    LoggingLevel.WARN,
                    'RenewalReminderService stopped after reaching the email limit: ' + lex.getMessage()
                );
                break;
            } catch (Exception ex) {
                System.debug(
                    LoggingLevel.ERROR,
                    'RenewalReminderService failed for ' + opportunityId + ': ' + ex.getMessage()
                );
            }
        }

        return sentCount;
    }
}
